<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');
$error='';$message=$_GET['message']??'';$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';else{
  $action=$_POST['action']??'';$id=(int)($_POST['id']??0);
  if($action==='save'){
   $title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$status=$_POST['status']??'draft';$allowed=['draft','active','paused','closed'];$start=trim($_POST['start_at']??'')?:null;$end=trim($_POST['end_at']??'')?:null;$anonymous=isset($_POST['allow_anonymous'])?'true':'false';
   if($title==='')$error='Campaign title is required.';elseif(!in_array($status,$allowed,true))$error='Invalid campaign status.';elseif($start&&$end&&strtotime($end)<=strtotime($start))$error='End date must be later than the start date.';else{
    if($id){$ok=pg_query_params($conn,'UPDATE feedback_campaigns SET title=$1,description=$2,status=$3,start_at=$4,end_at=$5,allow_anonymous=$6,updated_at=NOW() WHERE id=$7',[$title,$description,$status,$start,$end,$anonymous,$id]);}
    else{$ok=pg_query_params($conn,'INSERT INTO feedback_campaigns(title,description,status,start_at,end_at,allow_anonymous,created_by) VALUES($1,$2,$3,$4,$5,$6,$7)',[$title,$description,$status,$start,$end,$anonymous,$_SESSION['admin_id']]);}
    if($ok){audit_log($conn,$id?'feedback_campaign_updated':'feedback_campaign_created','feedback_campaign',$id?:null,['title'=>$title]);redirect('index.php?message=saved');}else $error='The campaign could not be saved.';
   }
  }elseif($action==='delete'&&$id){$count=pg_query_params($conn,'SELECT COUNT(*) FROM feedback_submissions WHERE campaign_id=$1',[$id]);if($count&&(int)pg_fetch_result($count,0,0)>0)$error='Campaigns with responses cannot be deleted. Close the campaign instead.';else{pg_query_params($conn,'DELETE FROM feedback_campaigns WHERE id=$1',[$id]);audit_log($conn,'feedback_campaign_deleted','feedback_campaign',$id);redirect('index.php?message=deleted');}}
 }
}
$editId=(int)($_GET['edit']??0);if($editId){$r=pg_query_params($conn,'SELECT * FROM feedback_campaigns WHERE id=$1',[$editId]);$edit=$r&&pg_num_rows($r)?pg_fetch_assoc($r):null;}
$showForm=($_GET['action']??'')==='new'||$edit||$error;$rows=pg_query($conn,"SELECT c.*,COUNT(DISTINCT q.id) questions,COUNT(DISTINCT p.id) participants,COUNT(DISTINCT s.id) responses FROM feedback_campaigns c LEFT JOIN feedback_questions q ON q.campaign_id=c.id LEFT JOIN feedback_participants p ON p.campaign_id=c.id LEFT JOIN feedback_submissions s ON s.campaign_id=c.id GROUP BY c.id ORDER BY c.created_at DESC");$summary=pg_query($conn,"SELECT COUNT(*) total,COUNT(*) FILTER(WHERE status='active') active,COUNT(*) FILTER(WHERE status='draft') draft,COUNT(*) FILTER(WHERE status='closed') closed FROM feedback_campaigns");$sum=$summary?pg_fetch_assoc($summary):['total'=>0,'active'=>0,'draft'=>0,'closed'=>0];admin_page_start('Campaigns','campaigns');?>
<div class="hero"><div><h2><i class="fas fa-bullhorn"></i> Feedback Campaigns</h2><p>Plan a questionnaire, invite participants, and control when responses are accepted.</p></div><?php if(!$showForm):?><a class="btn" href="?action=new"><i class="fa-solid fa-plus"></i> New Campaign</a><?php endif;?></div><div class="stats-grid"><div class="stat-card elections"><div class="stat-icon"><i class="fas fa-layer-group"></i></div><div><div class="stat-number"><?=(int)$sum['total']?></div><div class="stat-label">Total Campaigns</div></div></div><div class="stat-card votes"><div class="stat-icon"><i class="fas fa-signal"></i></div><div><div class="stat-number"><?=(int)$sum['active']?></div><div class="stat-label">Active</div></div></div><div class="stat-card positions"><div class="stat-icon"><i class="fas fa-pen-ruler"></i></div><div><div class="stat-number"><?=(int)$sum['draft']?></div><div class="stat-label">Draft</div></div></div><div class="stat-card turnout"><div class="stat-icon"><i class="fas fa-circle-check"></i></div><div><div class="stat-number"><?=(int)$sum['closed']?></div><div class="stat-label">Closed</div></div></div></div><?php if($message):?><div class="alert fms-flash" hidden data-swal-title="Campaign <?=h($message)?> successfully" data-swal-icon="success"></div><?php endif;?><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?>
<?php if($showForm):$v=$edit?:[];?><div class="card"><h3><?=$edit?'Edit campaign':'Create campaign'?></h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($v['id']??0)?>"><div class="field full"><label>Campaign title</label><input name="title" maxlength="180" required value="<?=h($_POST['title']??$v['title']??'')?>"></div><div class="field full"><label>Description / participant instructions</label><textarea name="description"><?=h($_POST['description']??$v['description']??'')?></textarea></div><div class="field"><label>Status</label><select name="status"><?php foreach(['draft'=>'Draft','active'=>'Active — accepting responses','paused'=>'Paused','closed'=>'Closed'] as $key=>$label):?><option value="<?=$key?>" <?=($_POST['status']??$v['status']??'draft')===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="field"><label>Response access</label><div class="choice"><i class="fa-solid fa-lock"></i> One-time participant credentials</div></div><div class="field"><label>Starts at (optional)</label><input type="datetime-local" name="start_at" value="<?=h(isset($v['start_at'])&&$v['start_at']?date('Y-m-d\TH:i',strtotime($v['start_at'])):'')?>"></div><div class="field"><label>Ends at (optional)</label><input type="datetime-local" name="end_at" value="<?=h(isset($v['end_at'])&&$v['end_at']?date('Y-m-d\TH:i',strtotime($v['end_at'])):'')?>"></div><div class="field full actions"><button class="btn">Save campaign</button><a class="btn secondary" href="index.php">Cancel</a></div></form></div><?php endif;?>
<div class="card"><div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Status</th><th>Questions</th><th>Participation</th><th>Actions</th></tr></thead><tbody><?php if($rows):while($c=pg_fetch_assoc($rows)):$pct=(int)$c['participants']?round((int)$c['responses']/(int)$c['participants']*100):0;?><tr><td><strong><?=h($c['title'])?></strong><div class="help"><?=h(mb_strimwidth($c['description'],0,90,'…'))?></div></td><td><span class="badge <?=h($c['status'])?>"><?=h(ucfirst($c['status']))?></span></td><td><?=(int)$c['questions']?></td><td><strong><?=(int)$c['responses']?> / <?=(int)$c['participants']?></strong><div class="help"><?=$pct?>% response rate</div></td><td><div class="actions"><a class="btn small secondary" href="?edit=<?=(int)$c['id']?>">Edit</a><a class="btn small secondary" href="../questions/index.php?campaign_id=<?=(int)$c['id']?>">Questions</a><a class="btn small secondary" href="../participants/index.php?campaign_id=<?=(int)$c['id']?>">Invite</a><a class="btn small" href="../responses/index.php?campaign_id=<?=(int)$c['id']?>">Results</a><a class="btn small secondary" href="../results/live.php?campaign_id=<?=(int)$c['id']?>"><i class="fa-solid fa-chart-line"></i> Live</a><form method="post" data-confirm-title="Delete campaign?" data-confirm="This empty campaign will be permanently deleted." data-confirm-button="Yes, delete it"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="btn small danger">Delete</button></form></div></td></tr><?php endwhile;endif;if(!$rows||pg_num_rows($rows)===0):?><tr><td colspan="5" class="empty">No campaigns yet. Create one to begin collecting feedback.</td></tr><?php endif;?></tbody></table></div></div><?php admin_page_end();?>
